function validate(input) {
  const [actions, values, timeDelays] = input;
  if (!Array.isArray(actions) || actions.length < 1 || actions.length > 100) return 'Give 1 to 100 actions.';
  if (!Array.isArray(values) || values.length !== actions.length) return 'values needs one argument list per action.';
  if (!Array.isArray(timeDelays) || timeDelays.length !== actions.length) return 'timeDelays needs one time per action.';
  if (actions[0] !== 'TimeLimitedCache' || timeDelays[0] !== 0) return 'The first action must be "TimeLimitedCache" at 0 ms.';
  const arity = { TimeLimitedCache: 0, set: 3, get: 1, count: 0 };
  for (let i = 0; i < actions.length; i++) {
    if (i > 0 && !['set', 'get', 'count'].includes(actions[i])) return 'After the first action, each action is "set", "get" or "count".';
    const args = values[i], time = timeDelays[i];
    if (!Array.isArray(args) || args.length !== arity[actions[i]] || !args.every(Number.isInteger)) return `${actions[i]} takes ${arity[actions[i]]} integer arguments.`;
    if (args.slice(0, 2).some((v) => v < 0 || v > 1e9)) return 'Keys and values are integers from 0 to 10^9.';
    if (actions[i] === 'set' && (args[2] < 0 || args[2] > 1000)) return 'A duration is from 0 to 1000 ms.';
    if (!Number.isInteger(time) || time < 0 || time > 1450) return 'Each time delay is an integer from 0 to 1450 ms.';
  }
  // Follow the actions in the order they run; an entry that is not replaced first expires at its end time.
  const order = actions.map((_, i) => i).slice(1).sort((a, b) => timeDelays[a] - timeDelays[b] || a - b);
  for (let p = 0; p < order.length; p++) {
    const i = order[p];
    if (actions[i] !== 'set') continue;
    const end = timeDelays[i] + values[i][2];
    let q = p + 1;
    while (q < order.length && timeDelays[order[q]] < end && !(actions[order[q]] === 'set' && values[order[q]][0] === values[i][0])) q++;
    if (q < order.length && timeDelays[order[q]] < end) continue;
    if (order.slice(p + 1).some((j) => timeDelays[j] === end)) return `The entry set by action ${i} expires at ${end} ms, when another action runs; move one of them by a millisecond.`;
  }
  return null;
}

