function adapt(input, solve, kit) {
  const [actions, values, timeDelays] = input;
  const cache = new solve();
  for (const name of ['set', 'get', 'count']) if (!cache || typeof cache[name] !== 'function') throw new Error(`TimeLimitedCache needs a method ${name}.`);
  kit.trace('new TimeLimitedCache() is created');
  const results = actions.map(() => null);
  let failure = null;
  for (let i = 1; i < actions.length; i++) {
    setTimeout(() => {
      const name = actions[i], args = values[i], result = cache[name](...args);
      const expected = name === 'set' ? typeof result === 'boolean' : Number.isInteger(result);
      if (!expected) failure = failure ?? `${name}(${args.join(', ')}) returned ${String(result)}; it should return ${name === 'set' ? 'true or false' : 'an integer'}.`;
      results[i] = result === undefined ? null : result;
      kit.trace(`${name}(${args.join(', ')}) returns ${String(result)}`);
    }, timeDelays[i]);
  }
  // Every action has run once the latest time delay has passed.
  return new Promise((resolve, reject) => setTimeout(() => (failure ? reject(new Error(failure)) : resolve(results)), Math.max(...timeDelays) + 1));
}

