class TimeLimitedCache {
  constructor() {
    this.entries = new Map();
  }

  // An entry is alive while the clock has not reached its expiry time.
  alive(key) {
    const entry = this.entries.get(key);
    return entry !== undefined && Date.now() < entry.expiresAt;
  }

  set(key, value, duration) {
    const existed = this.alive(key);
    this.entries.set(key, { value, expiresAt: Date.now() + duration });
    return existed;
  }

  get(key) {
    return this.alive(key) ? this.entries.get(key).value : -1;
  }

  count() {
    return [...this.entries.keys()].filter((key) => this.alive(key)).length;
  }
}

